macro_rules! nghttp2_mem {
    () => {
        # [doc = " @struct"] # [doc = ""] # [doc = " Custom memory allocator functions and user defined pointer.  The"] # [doc = " |mem_user_data| member is passed to each allocator function.  This"] # [doc = " can be used, for example, to achieve per-session memory pool."] # [doc = ""] # [doc = " In the following example code, ``my_malloc``, ``my_free``,"] # [doc = " ``my_calloc`` and ``my_realloc`` are the replacement of the"] # [doc = " standard allocators ``malloc``, ``free``, ``calloc`` and"] # [doc = " ``realloc`` respectively::"] # [doc = ""] # [doc = "     void *my_malloc_cb(size_t size, void *mem_user_data) {"] # [doc = "       return my_malloc(size);"] # [doc = "     }"] # [doc = ""] # [doc = "     void my_free_cb(void *ptr, void *mem_user_data) { my_free(ptr); }"] # [doc = ""] # [doc = "     void *my_calloc_cb(size_t nmemb, size_t size, void *mem_user_data) {"] # [doc = "       return my_calloc(nmemb, size);"] # [doc = "     }"] # [doc = ""] # [doc = "     void *my_realloc_cb(void *ptr, size_t size, void *mem_user_data) {"] # [doc = "       return my_realloc(ptr, size);"] # [doc = "     }"] # [doc = ""] # [doc = "     void session_new() {"] # [doc = "       nghttp2_session *session;"] # [doc = "       nghttp2_session_callbacks *callbacks;"] # [doc = "       nghttp2_mem mem = {NULL, my_malloc_cb, my_free_cb, my_calloc_cb,"] # [doc = "                          my_realloc_cb};"] # [doc = ""] # [doc = "       ..."] # [doc = ""] # [doc = "       nghttp2_session_client_new3(&session, callbacks, NULL, NULL, &mem);"] # [doc = ""] # [doc = "       ..."] # [doc = "     }"] # [repr (C)] # [derive (Debug , Copy , Clone)] pub struct nghttp2_mem { # [doc = " An arbitrary user supplied data.  This is passed to each"] # [doc = " allocator function."] pub mem_user_data : * mut :: std :: os :: raw :: c_void , # [doc = " Custom allocator function to replace malloc()."] pub malloc : nghttp2_malloc , # [doc = " Custom allocator function to replace free()."] pub free : nghttp2_free , # [doc = " Custom allocator function to replace calloc()."] pub calloc : nghttp2_calloc , # [doc = " Custom allocator function to replace realloc()."] pub realloc : nghttp2_realloc , }
    };
}

nghttp2_mem!()